     1→import { IDisposable } from '@lumino/disposable';
     2→import { PromiseDelegate } from '@lumino/coreutils';
     3→import { ServerConnection } from '@jupyterlab/services';
     4→import { URLExt } from '@jupyterlab/coreutils';
     5→import { AiCompleterService as AiService } from './types';
     6→import { Signal, ISignal } from '@lumino/signaling';
     7→
     8→const SERVICE_URL = 'api/ai/completion/inline';
     9→
    10→type StreamChunk = AiService.InlineCompletionStreamChunk;
    11→
    12→export class CompletionWebsocketHandler implements IDisposable {
    13→  /**
    14→   * The server settings used to make API requests.
    15→   */
    16→  readonly serverSettings: ServerConnection.ISettings;
    17→
    18→  /**
    19→   * Create a new completion handler.
    20→   */
    21→  constructor(options: AiService.IOptions = {}) {
    22→    this.serverSettings =
    23→      options.serverSettings ?? ServerConnection.makeSettings();
    24→  }
    25→
    26→  /**
    27→   * Initializes the WebSocket connection to the completion backend. Promise is
    28→   * resolved when server acknowledges connection and sends the client ID. This
    29→   * must be awaited before calling any other method.
    30→   */
    31→  public async initialize(): Promise<void> {
    32→    await this._initialize();
    33→  }
    34→
    35→  /**
    36→   * Sends a message across the WebSocket. Promise resolves to the message ID
    37→   * when the server sends the same message back, acknowledging receipt.
    38→   */
    39→  public sendMessage(
    40→    message: AiService.InlineCompletionRequest
    41→  ): Promise<AiService.InlineCompletionReply> {
    42→    return new Promise(resolve => {
    43→      this._socket?.send(JSON.stringify(message));
    44→      this._replyForResolver[message.number] = resolve;
    45→    });
    46→  }
    47→
    48→  /**
    49→   * Signal emitted when a new chunk of completion is streamed.
    50→   */
    51→  get streamed(): ISignal<CompletionWebsocketHandler, StreamChunk> {
    52→    return this._streamed;
    53→  }
    54→
    55→  /**
    56→   * Whether the completion handler is disposed.
    57→   */
    58→  get isDisposed(): boolean {
    59→    return this._isDisposed;
    60→  }
    61→
    62→  /**
    63→   * Dispose the completion handler.
    64→   */
    65→  dispose(): void {
    66→    if (this.isDisposed) {
    67→      return;
    68→    }
    69→    this._isDisposed = true;
    70→
    71→    // Clean up socket.
    72→    const socket = this._socket;
    73→    if (socket) {
    74→      this._socket = null;
    75→      socket.onopen = () => undefined;
    76→      socket.onerror = () => undefined;
    77→      socket.onmessage = () => undefined;
    78→      socket.onclose = () => undefined;
    79→      socket.close();
    80→    }
    81→  }
    82→
    83→  private _onMessage(message: AiService.CompleterMessage): void {
    84→    switch (message.type) {
    85→      case 'connection': {
    86→        this._initialized.resolve();
    87→        break;
    88→      }
    89→      case 'stream': {
    90→        this._streamed.emit(message);
    91→        break;
    92→      }
    93→      default: {
    94→        if (message.reply_to in this._replyForResolver) {
    95→          this._replyForResolver[message.reply_to](message);
    96→          delete this._replyForResolver[message.reply_to];
    97→        } else {
    98→          console.warn('Unhandled message', message);
    99→        }
   100→        break;
   101→      }
   102→    }
   103→  }
   104→
   105→  /**
   106→   * Dictionary mapping message IDs to Promise resolvers.
   107→   */
   108→  private _replyForResolver: Record<
   109→    number,
   110→    (value: AiService.InlineCompletionReply) => void
   111→  > = {};
   112→
   113→  private _onClose(e: CloseEvent, reject: any) {
   114→    reject(new Error('Inline completion websocket disconnected'));
   115→    console.error('Inline completion websocket disconnected');
   116→    // only attempt re-connect if there was an abnormal closure
   117→    // WebSocket status codes defined in RFC 6455: https://www.rfc-editor.org/rfc/rfc6455.html#section-7.4.1
   118→    if (e.code === 1006) {
   119→      const delaySeconds = 1;
   120→      console.info(`Will try to reconnect in ${delaySeconds} s.`);
   121→      setTimeout(async () => await this._initialize(), delaySeconds * 1000);
   122→    }
   123→  }
   124→
   125→  private async _initialize(): Promise<void> {
   126→    if (this.isDisposed) {
   127→      return;
   128→    }
   129→    const promise = new PromiseDelegate<void>();
   130→    this._initialized = promise;
   131→    console.log(
   132→      'Creating a new websocket connection for inline completions...'
   133→    );
   134→    const { token, WebSocket, wsUrl } = this.serverSettings;
   135→    const url =
   136→      URLExt.join(wsUrl, SERVICE_URL) +
   137→      (token ? `?token=${encodeURIComponent(token)}` : '');
   138→
   139→    const socket = (this._socket = new WebSocket(url));
   140→    socket.onclose = e => this._onClose(e, promise.reject);
   141→    socket.onerror = e => promise.reject(e);
   142→    socket.onmessage = msg => msg.data && this._onMessage(JSON.parse(msg.data));
   143→  }
   144→
   145→  private _isDisposed = false;
   146→  private _socket: WebSocket | null = null;
   147→  private _streamed = new Signal<CompletionWebsocketHandler, StreamChunk>(this);
   148→  private _initialized: PromiseDelegate<void> = new PromiseDelegate<void>();
   149→}
