    10→import { Notification, showErrorMessage } from '@jupyterlab/apputils';
    11→import { JSONValue, PromiseDelegate } from '@lumino/coreutils';
    12→import { ISignal, Signal } from '@lumino/signaling';
    13→import {
    14→  IEditorLanguageRegistry,
    15→  IEditorLanguage
    16→} from '@jupyterlab/codemirror';
    17→import { NotebookPanel } from '@jupyterlab/notebook';
    18→import { IJaiCompletionProvider } from '../tokens';
    19→import { AiCompleterService as AiService } from './types';
    20→import { DocumentWidget } from '@jupyterlab/docregistry';
    21→import { jupyternautIcon } from '../icons';
    22→import { CompletionWebsocketHandler } from './handler';
    23→
    24→type StreamChunk = AiService.InlineCompletionStreamChunk;
    25→
    26→/**
    27→ * Format the language name nicely.
    28→ */
    29→export function displayName(language: IEditorLanguage): string {
    30→  if (language.name === 'ipythongfm') {
    31→    return 'Markdown (IPython)';
    32→  }
    33→  if (language.name === 'ipython') {
    34→    return 'IPython';
    35→  }
    36→  return language.displayName ?? language.name;
    37→}
