    39→export class JaiInlineProvider
    40→  implements IInlineCompletionProvider, IJaiCompletionProvider
    41→{
    42→  readonly identifier = JaiInlineProvider.ID;
    43→  readonly icon = jupyternautIcon.bindprops({ width: 16, top: 1 });
    44→
    45→  constructor(protected options: JaiInlineProvider.IOptions) {
    46→    options.completionHandler.streamed.connect(this._receiveStreamChunk, this);
    47→  }
    48→
    49→  get name(): string {
    50→    return 'JupyterAI';
    51→  }
    52→
    53→  async fetch(
    54→    request: CompletionHandler.IRequest,
    55→    context: IInlineCompletionContext
    56→  ): Promise<IInlineCompletionList<IInlineCompletionItem>> {
    57→    const mime = request.mimeType ?? 'text/plain';
    58→    const language = this.options.languageRegistry.findByMIME(mime);
    59→    if (!language) {
    60→      console.warn(
    61→        `Could not recognise language for ${mime} - cannot complete`
    62→      );
    63→      return { items: [] };
    64→    }
    65→    if (!this.isLanguageEnabled(language?.name)) {
    66→      // Do not offer suggestions if disabled.
    67→      return { items: [] };
    68→    }
    69→    let cellId = undefined;
    70→    let path = context.session?.path;
    71→    if (context.widget instanceof NotebookPanel) {
    72→      const activeCell = context.widget.content.activeCell;
    73→      if (activeCell) {
    74→        cellId = activeCell.model.id;
    75→      }
    76→    }
    77→    if (!path && context.widget instanceof DocumentWidget) {
    78→      path = context.widget.context.path;
    79→    }
    80→    const number = ++this._counter;
    81→
    82→    const streamPreference = this._settings.streaming;
    83→    const stream =
    84→      streamPreference === 'always'
    85→        ? true
    86→        : streamPreference === 'never'
    87→        ? false
    88→        : context.triggerKind === InlineCompletionTriggerKind.Invoke;
    89→
    90→    if (stream) {
    91→      // Reset stream promises handler
    92→      this._streamPromises.clear();
    93→    }
    94→    const result = await this.options.completionHandler.sendMessage({
    95→      path: context.session?.path,
    96→      mime,
    97→      prefix: this._prefixFromRequest(request),
    98→      suffix: this._suffixFromRequest(request),
    99→      language: this._resolveLanguage(language),
   100→      number,
   101→      stream,
   102→      cell_id: cellId
   103→    });
   104→
   105→    const error = result.error;
   106→    if (error) {
   107→      Notification.emit(`Inline completion failed: ${error.type}`, 'error', {
   108→        autoClose: false,
   109→        actions: [
   110→          {
   111→            label: 'Show Traceback',
   112→            callback: () => {
   113→              showErrorMessage('Inline completion failed on the server side', {
   114→                message: error.traceback
   115→              });
   116→            }
   117→          }
   118→        ]
   119→      });
   120→      throw new Error(
   121→        `Inline completion failed: ${error.type}\n${error.traceback}`
   122→      );
   123→    }
   124→    return result.list;
   125→  }
   126→
   127→  /**
   128→   * Stream a reply for completion identified by given `token`.
   129→   */
   130→  async *stream(token: string): AsyncGenerator<StreamChunk, void, unknown> {
   131→    let done = false;
   132→    while (!done) {
   133→      const delegate = new PromiseDelegate<StreamChunk>();
   134→      this._streamPromises.set(token, delegate);
   135→      const promise = delegate.promise;
   136→      yield promise;
   137→      done = (await promise).done;
   138→    }
   139→  }
   140→
   141→  get schema(): ISettingRegistry.IProperty {
   142→    const knownLanguages = this.options.languageRegistry.getLanguages();
   143→    return {
   144→      properties: {
   145→        maxPrefix: {
   146→          title: 'Maximum prefix length',
   147→          minimum: 1,
   148→          type: 'number',
   149→          description:
   150→            'At most how many prefix characters should be provided to the model.'
   151→        },
   152→        maxSuffix: {
   153→          title: 'Maximum suffix length',
   154→          minimum: 0,
   155→          type: 'number',
   156→          description:
   157→            'At most how many suffix characters should be provided to the model.'
   158→        },
   159→        disabledLanguages: {
   160→          title: 'Disabled languages',
   161→          type: 'array',
   162→          items: {
   163→            type: 'string',
   164→            oneOf: knownLanguages.map(language => {
   165→              return { const: language.name, title: displayName(language) };
   166→            })
   167→          },
   168→          description:
   169→            'Languages for which the completions should not be shown.'
   170→        },
   171→        streaming: {
   172→          title: 'Streaming',
   173→          type: 'string',
   174→          oneOf: [
   175→            { const: 'always', title: 'Always' },
   176→            { const: 'manual', title: 'When invoked manually' },
   177→            { const: 'never', title: 'Never' }
   178→          ],
   179→          description: 'Whether to show suggestions as they are generated'
   180→        }
   181→      },
   182→      default: JaiInlineProvider.DEFAULT_SETTINGS as any
   183→    };
   184→  }
   185→
   186→  async configure(settings: { [property: string]: JSONValue }): Promise<void> {
   187→    this._settings = settings as unknown as JaiInlineProvider.ISettings;
   188→    this._settingsChanged.emit();
   189→  }
   190→
   191→  isEnabled(): boolean {
   192→    return this._settings.enabled;
   193→  }
   194→
   195→  isLanguageEnabled(language: string): boolean {
   196→    return !this._settings.disabledLanguages.includes(language);
   197→  }
   198→
   199→  get settingsChanged(): ISignal<JaiInlineProvider, void> {
   200→    return this._settingsChanged;
   201→  }
   202→
   203→  /**
   204→   * Process the stream chunk to make it available in the awaiting generator.
   205→   */
   206→  private _receiveStreamChunk(
   207→    _emitter: CompletionWebsocketHandler,
   208→    chunk: StreamChunk
   209→  ) {
   210→    const token = chunk.response.token;
   211→    if (!token) {
   212→      throw Error('Stream chunks must return define `token` in `response`');
   213→    }
   214→    const delegate = this._streamPromises.get(token);
   215→    if (!delegate) {
   216→      console.warn('Unhandled stream chunk');
   217→    } else {
   218→      delegate.resolve(chunk);
   219→      if (chunk.done) {
   220→        this._streamPromises.delete(token);
   221→      }
   222→    }
   223→  }
   224→
   225→  /**
   226→   * Extract prefix from request, accounting for context window limit.
   227→   */
   228→  private _prefixFromRequest(request: CompletionHandler.IRequest): string {
   229→    const textBefore = request.text.slice(0, request.offset);
   230→    const prefix = textBefore.slice(
   231→      -Math.min(this._settings.maxPrefix, textBefore.length)
   232→    );
   233→    return prefix;
   234→  }
   235→
   236→  /**
   237→   * Extract suffix from request, accounting for context window limit.
   238→   */
   239→  private _suffixFromRequest(request: CompletionHandler.IRequest): string {
   240→    const textAfter = request.text.slice(request.offset);
   241→    const prefix = textAfter.slice(
   242→      0,
   243→      Math.min(this._settings.maxPrefix, textAfter.length)
   244→    );
   245→    return prefix;
   246→  }
   247→
   248→  private _resolveLanguage(language: IEditorLanguage | null) {
   249→    if (!language) {
   250→      return 'plain English';
   251→    }
   252→    if (language.name === 'ipython') {
   253→      return 'python';
   254→    } else if (language.name === 'ipythongfm') {
   255→      return 'markdown';
   256→    }
   257→    return language.name;
   258→  }
   259→
   260→  private _settings: JaiInlineProvider.ISettings =
   261→    JaiInlineProvider.DEFAULT_SETTINGS;
   262→  private _settingsChanged = new Signal<JaiInlineProvider, void>(this);
   263→
   264→  private _streamPromises: Map<string, PromiseDelegate<StreamChunk>> =
   265→    new Map();
   266→  private _counter = 0;
   267→}
   268→
   269→export namespace JaiInlineProvider {
   270→  export const ID = '@jupyterlab/jupyter-ai';
   271→
   272→  export interface IOptions {
   273→    completionHandler: CompletionWebsocketHandler;
   274→    languageRegistry: IEditorLanguageRegistry;
   275→  }
   276→
   277→  export interface ISettings {
   278→    maxPrefix: number;
   279→    maxSuffix: number;
   280→    debouncerDelay: number;
   281→    enabled: boolean;
   282→    disabledLanguages: string[];
   283→    streaming: 'always' | 'manual' | 'never';
   284→  }
   285→
   286→  export const DEFAULT_SETTINGS: ISettings = {
   287→    maxPrefix: 10000,
   288→    maxSuffix: 10000,
   289→    // The debouncer delay handling is implemented upstream in JupyterLab;
   290→    // here we just increase the default from 0, as compared to kernel history
   291→    // the external AI models may have a token cost associated.
   292→    debouncerDelay: 250,
   293→    enabled: false,
   294→    // ipythongfm means "IPython GitHub Flavoured Markdown"
   295→    disabledLanguages: ['ipythongfm'],
   296→    streaming: 'manual'
   297→  };
   298→}
