     2→  IInlineCompletionList,
     3→  IInlineCompletionItem
     4→} from '@jupyterlab/completer';
     5→
     6→import { ServerConnection } from '@jupyterlab/services';
     7→
     8→export namespace AiCompleterService {
     9→  /**
    10→   * The instantiation options for a data registry handler.
    11→   */
    12→  export interface IOptions {
    13→    serverSettings?: ServerConnection.ISettings;
    14→  }
    15→
    16→  export type ConnectionMessage = {
    17→    type: 'connection';
    18→    client_id: string;
    19→  };
    20→
    21→  export type InlineCompletionRequest = {
    22→    number: number;
    23→    path?: string;
    24→    /* The model has to complete given prefix */
    25→    prefix: string;
    26→    /* The model may consider the following suffix */
    27→    suffix: string;
    28→    mime: string;
    29→    /* Whether to stream the response (if streaming is supported by the model) */
    30→    stream: boolean;
    31→    language?: string;
    32→    cell_id?: string;
    33→  };
    34→
    35→  export type CompletionError = {
    36→    type: string;
    37→    traceback: string;
    38→  };
    39→
    40→  export type InlineCompletionReply = {
    41→    /**
    42→     * Type for this message can be skipped (`inline_completion` is presumed default).
    43→     **/
    44→    type?: 'inline_completion';
    45→    list: IInlineCompletionList;
    46→    reply_to: number;
    47→    error?: CompletionError;
    48→  };
    49→
    50→  export type InlineCompletionStreamChunk = {
    51→    type: 'stream';
    52→    response: IInlineCompletionItem;
    53→    reply_to: number;
    54→    done: boolean;
    55→  };
    56→
    57→  export type CompleterMessage =
    58→    | InlineCompletionReply
    59→    | ConnectionMessage
    60→    | InlineCompletionStreamChunk;
    61→}
